var q = kit.earthquake({});
addLabel('البؤرة', q.points.focus[0], q.points.focus[1], q.points.focus[2]);
addLabel('المركز السطحي', q.points.epicenter[0], q.points.epicenter[1], q.points.epicenter[2]);
addLabel('الصدع', q.points.fault[0], q.points.fault[1], q.points.fault[2]);
addLabel('القشرة الأرضية', q.points.crust[0], q.points.crust[1], q.points.crust[2]);
addLabel('الصفائح الصخرية', q.points.plates[0], q.points.plates[1], q.points.plates[2]);
var mag = 5;
ui.slider('قوة الزلزال', 1, 9, 5, 1, 'ريختر', function(v){ mag = v; });
ui.button('⚡ ابدأ الزلزال', function(){
  q.reset();
  q.quake(mag);
  var msg;
  if (mag <= 3) msg = 'قوة ' + mag + ': زلزال ضعيف، اهتزاز خفيف لا نكاد نشعر به.';
  else if (mag <= 5) msg = 'قوة ' + mag + ': اهتزت الأرض بوضوح لكن لم تتشقق.';
  else if (mag === 6) msg = 'قوة 6: تشققت الأرض على الصدع وانزاح الطريق.';
  else msg = 'قوة ' + mag + ': زلزال قوي، تشققت الأرض وانهارت المباني.';
  ui.result(msg);
});
ui.button('↺ أعد الأرض', function(){
  q.reset();
  ui.result('عادت الأرض كما كانت. جرّب قوة مختلفة.');
});
ui.result('الصفائح الصخرية تنزلق فتتكسر الصخور وتهتز الأرض.');

var v = kit.volcano({cutaway:true});
addLabel('الصهارة', v.points.chamber[0], v.points.chamber[1], v.points.chamber[2]);
addLabel('الفتحة (الفوهة)', v.points.crater[0], v.points.crater[1], v.points.crater[2]);
addLabel('اللابة', v.points.lava[0], v.points.lava[1], v.points.lava[2]);
addLabel('الرماد والغازات', v.points.ash[0], v.points.ash[1], v.points.ash[2]);
addLabel('القشرة الأرضية', v.points.crust[0], v.points.crust[1], v.points.crust[2]);
var power = 0.6;
ui.slider('قوة اندفاع الصهارة', 0.1, 1, 0.6, 0.1, '', function(x){ power = x; });
ui.button('🌋 فجّر البركان', function(){
  v.erupt(power);
  if (power < 0.4) ui.result('ثوران هادئ: خرجت الصهارة فصارت لابة تسيل على السفح.');
  else if (power < 0.8) ui.result('ثوران متوسط: لابة تسيل، ومعها صخور ودخان ورماد.');
  else ui.result('ثوران قوي: اندفعت الصهارة بقوة فخرجت اللابة والصخور والغازات والرماد.');
});
ui.button('😴 هدّئ البركان', function(){
  v.calm();
  ui.result('هدأ البركان. تبرد اللابة وتتراكم فيكبر البركان مع الزمن.');
});
ui.result('الصهارة تحت الأرض، وعندما تصل إلى السطح تسمى اللابة.');
